#!/usr/bin/env python3
"""Scan friend branches for Friend-Message commits and report which are not yet transcribed on main."""
import subprocess, sys, re, os

REPO = "/tmp/ross-main"
BRANCHES = ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]

def git(*args, cwd=REPO):
    return subprocess.run(["git", "-C", cwd] + list(args), capture_output=True, text=True).stdout

# SHAs already recorded in episode files
transcribed = set()
for f in sorted(os.listdir(os.path.join(REPO, "S05"))) and []:
    pass
import glob
for path in glob.glob(os.path.join(REPO, "S0*", "E*.md")):
    with open(path, encoding="utf-8") as fh:
        transcribed.update(re.findall(r"[0-9a-f]{40}", fh.read()))

missing = []
for b in BRANCHES:
    shas = git("log", "--format=%H", "origin/friend/%s" % b).split()
    for s in shas:
        body = git("show", "-s", "--format=%B", s)
        if re.search(r"^Friend-Message: 1\s*$", body, re.M):
            if s not in transcribed:
                missing.append((b, s))

def key(item):
    b, s = item
    ts = git("show", "-s", "--format=%cI", s).strip()
    return (ts, s)

missing.sort(key=key)
for b, s in missing:
    body = git("show", "-s", "--format=%B", s)
    m = re.search(r"^Episode: (\S+)", body, re.M)
    ep = m.group(1) if m else "?"
    reply = re.search(r"^Reply-To: (\S*)", body, re.M)
    ts = git("show", "-s", "--format=%cI", s).strip()
    print("%s %s %s ep=%s reply=%s ts=%s" % (ts, b, s, ep, reply.group(1) if reply else "-", ts))
print("TOTAL MISSING:", len(missing))

